# apply_ensemble15_and_run.py — bumps ensemble from 5 to 15 seeds and
# adds --drop-driver flag to test predictions without the driver categorical.
import base64, pathlib, subprocess, sys

FILES = {
    'src/cli/predict_next.py': '',
}


def main():
    for target, b64 in FILES.items():
        p = pathlib.Path(target)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(b64))
        print(f"wrote {target}")
    print("\nRun full ensemble (baseline):  python -m src.cli.predict_next --no-refresh")
    print("Run without driver categorical: python -m src.cli.predict_next --no-refresh --drop-driver")

if __name__ == "__main__":
    main()
